1	//! The local `callisto release` route: select every unreleased package and
2	//! derive its intent, for both the preview and the run.
3	
4	use std::path::Path;
5	
6	use callisto_model::{
7	    CommandRunner, ExecutionTrustProfileV1, ManifestFormat, PublishTarget, ReleaseIntentV1, ReleasePackageId,
8	    SourceIdentity,
9	};
