23	/// How a local release observes its source commit.
24	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
25	pub enum LocalReleaseSource {
26	    /// `--dry-run`: HEAD's commit, whatever the worktree state.
27	    Preview,
28	    /// A real run: HEAD's commit from a clean worktree, on any branch.
29	    Trusted,
30	}
