149	/// A derived local release.
150	#[derive(Clone, Debug, PartialEq, Eq)]
151	pub struct LocalReleasePlan {
152	    pub intent: ReleaseIntentV1,
153	    /// A preview only: `origin` has no push URL, so tags carry no remote and a run would refuse.
154	    pub tags_unbound: bool,
155	    /// Advisory findings from derivation (e.g. an artifact owner selected without its product).
156	    pub diagnostics: Vec<callisto_model::Diagnostic>,
157	}
158	
159	/// Derives the intent for every unreleased package (or exactly `selections`).
160	///
161	/// This is the one plan derivation behind both `callisto release --dry-run`
162	/// and `callisto release`; `None` means nothing is unreleased.
163	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
164	    root: &Path,
165	    locator: &L,
166	    runner: &R,
167	    selections: &[ReleasePackageId],
168	    mode: LocalReleaseSource,
169	) -> Result<Option<LocalReleasePlan>, GraphError> {
170	    let root = canonical_root(root)?;
171	    let workspace = Workspace::load(root, locator, runner)?;
172	    plan_release(&workspace, selections, mode, true)
173	}
174	
175	/// The tagged releases on HEAD whose operations are not all observed satisfied: a rerun finishes them.
176	///
177	/// A tag proves only that the tag was created. Releases tagged on an older commit are settled and
178	/// never observed, so only a rerun at the release commit reaches the providers.
179	fn incomplete_tagged_releases<R: CommandRunner, D: DependencyResolver>(
180	    workspace: &Workspace<'_, R, D>,
181	    mode: LocalReleaseSource,
182	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
183	    let head = workspace.git_access().head_sha()?;
184	    let tagged: std::collections::BTreeSet<ReleasePackageId> =
185	        crate::commands::release_decision::releases_tagged_at(workspace, &head)?
186	            .into_iter()
187	            .map(|entry| entry.package)
188	            .collect();
189	    if tagged.is_empty() {
190	        return Ok(tagged);
191	    }
192	    // Without an `origin` push URL a preview cannot observe anything, so it cannot call a tagged release finished.
193	    if mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none() {
194	        return Ok(tagged);
195	    }
196	    let profile = ExecutionTrustProfileV1::GitCommit;
197	    let source = match mode {
198	        LocalReleaseSource::Preview => SourceIdentity::GitCommit { sha: head },
199	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
200	    };
201	    // The roster a run would plan with every tagged release still open, so a dependency left untagged by the
202	    // failed run is part of it and the dependency checks see the same packages as the real derivation.
203	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, &[], &tagged)? else {
204	        return Ok(Default::default());
205	    };
206	    let (_, prepared) =
207	        derive_release_intent_with_prepared(workspace, &decision, source, profile, None, &mut Vec::new())?;
208	    Ok(unsatisfied_packages(
209	        &workspace.root,
210	        workspace.runner,
211	        &prepared,
212	        &tagged,
213	    ))
214	}
215	
216	/// The packages in `decision` this repository has never tagged.
217	fn first_release_packages<R: CommandRunner, D: DependencyResolver>(
218	    workspace: &Workspace<'_, R, D>,
219	    decision: &callisto_model::ReleaseDecisionV1,
220	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
221	    let tags = workspace.tags()?;
222	    Ok(decision
223	        .entries
224	        .iter()
225	        .filter(|entry| {
226	            crate::commands::release_decision::workspace_package(workspace, &entry.package)
227	                .is_some_and(|package| tags.last_tag(&package.id).is_none())
228	        })
229	        .map(|entry| entry.package.clone())
230	        .collect())
231	}
232	
233	/// Refuses a first release to crates.io of a crate that lacks the metadata crates.io requires.
234	///
235	/// Cargo only warns about it locally; crates.io rejects the upload, which can land after other packages published.
236	fn refuse_a_crate_crates_io_would_reject<R: CommandRunner, D: DependencyResolver>(
237	    workspace: &Workspace<'_, R, D>,
238	    decision: &callisto_model::ReleaseDecisionV1,
239	) -> Result<(), GraphError> {
240	    for id in first_release_packages(workspace, decision)? {
241	        let Some(package) = crate::commands::release_decision::workspace_package(workspace, &id) else {
242	            continue;
243	        };
244	        if !package.publish_to.contains(&PublishTarget::CratesIo) {
245	            continue;
246	        }
247	        let Some(manifest) = package
248	            .canonical_manifests()
249	            .find(|manifest| manifest.format == ManifestFormat::CargoToml)
250	            .map(|manifest| manifest.path.clone())
251	        else {
252	            continue;
253	        };
254	        let Some(text) = callisto_manifests::read_manifest_text(&workspace.root)(&manifest)? else {
255	            continue;
256	        };
257	        let document = callisto_manifests::parse_manifest(&manifest, &text)?;
258	        let root = callisto_manifests::enclosing_workspace_manifest(&workspace.root, &manifest, &document)?;
259	        let root_document = match root {
260	            Some(root) => callisto_manifests::read_manifest_text(&workspace.root)(&root)?
261	                .map(|text| callisto_manifests::parse_manifest(&root, &text))
262	                .transpose()?,
263	            None => None,
264	        };
265	        let missing = callisto_manifests::missing_crates_io_metadata(&document, root_document.as_ref());
266	        if !missing.is_empty() {
267	            return Err(GraphError::ReleaseMetadataMissing {
268	                package: id.to_string(),
269	                missing: missing.join(" or "),
270	            });
271	        }
272	    }
273	    Ok(())
274	}
275	
276	/// Refuses a first release whose name another project already owns.
277	///
278	/// A package this repository has never tagged has no history here, so a version of it that the registry already holds
279	/// under a different repository is that project's, not ours; adopting it would tag this commit as their release.
280	/// A package that has a tag is left alone: its published versions are its own history.
281	fn refuse_a_name_another_project_owns<R: CommandRunner, D: DependencyResolver>(
282	    workspace: &Workspace<'_, R, D>,
283	    decision: &callisto_model::ReleaseDecisionV1,
284	    source: &SourceIdentity,
285	    profile: ExecutionTrustProfileV1,
286	    mode: LocalReleaseSource,
287	) -> Result<(), GraphError> {
288	    let first_releases = first_release_packages(workspace, decision)?;
289	    // Without an `origin` push URL a preview cannot tell whose repository the registry names.
290	    if first_releases.is_empty()
291	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
292	    {
293	        return Ok(());
294	    }
295	    let (_, prepared) =
296	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
297	    match names_taken_by_other_projects(&workspace.root, workspace.runner, &prepared, &first_releases)?
298	        .into_iter()
299	        .next()
300	    {
