fn file_sha256(path: &Path) -> Result<String, GraphError> {
    let file = std::fs::File::open(path).map_err(io_error)?;
    let (digest, _) = callisto_model::ArtifactDigest::from_reader(file).map_err(io_error)?;
    Ok(digest.as_str().to_owned())
}

