1	//! The tag role: a local annotated tag plus the push that makes it remote.
2	
3	use std::path::Path;
4	
5	use callisto_model::vcs::{GitAccess, TagSignPolicy};
6	use callisto_model::{
7	    CommandRunner, CommitSha, ExactEvidence, ProviderConflictReason, ProviderEvidenceV1, ProviderIndeterminateCause,
8	    ProviderObservationV1, TagName,
9	};
10	
11	use crate::error::{CommandFailure, RemoteConflict};
12	use crate::GraphError;
13	
14	use super::policy::{self, programs, run_observation, timeouts, Attempt};
15	use super::{
16	    confirmed_evidence, wrong_role, EffectAuthorization, PreparedOperation, ProviderCapabilities, ProviderContext,
17	    ProviderRequest, ReleaseProvider, TagOperation,
18	};
19	
20	/// What the local repository holds at `refs/tags/<name>`; identity is the target commit plus being annotated.
21	#[derive(Debug, PartialEq, Eq)]
22	enum LocalTagObservation {
23	    Absent,
24	    Annotated {
25	        target: CommitSha,
26	    },
27	    /// A lightweight tag, or any other object this adapter did not write.
28	    Unannotated,
29	}
30	
31	/// What the prepared remote holds at `refs/tags/<name>`. `ls-remote` cannot
32	/// read annotation text, so only the tagged commit is comparable.
33	#[derive(Debug, PartialEq, Eq)]
34	enum RemoteTagObservation {
35	    Absent,
36	    Annotated { target: CommitSha },
37	    Unannotated,
38	    Indeterminate,
39	}
40	
41	pub(crate) struct TagProvider;
42	
43	impl ReleaseProvider for TagProvider {
44	    fn capabilities(&self) -> ProviderCapabilities {
45	        ProviderCapabilities {
46	            can_observe: true,
47	            can_publish: true,
48	        }
49	    }
50	
51	    fn preflight_conflict(&self) -> RemoteConflict {
52	        RemoteConflict::TagTargetDiffers
53	    }
54	
55	    fn observe(
56	        &self,
57	        context: &ProviderContext<'_>,
58	        request: &ProviderRequest<'_>,
59	    ) -> Result<ProviderObservationV1, GraphError> {
60	        tag_observation(context, tag_operation(request)?)
61	    }
62	
63	    fn publish(
64	        &self,
65	        context: &ProviderContext<'_>,
66	        request: &ProviderRequest<'_>,
67	        effect: &EffectAuthorization<'_>,
68	    ) -> Result<ExactEvidence, GraphError> {
69	        let operation = tag_operation(request)?;
70	        // The preflight observation already proved the remote absent. It leaves
71	        // exactly as prepared by a run whose push failed; only the push remains.
72	        if observed_local_tag(context, &operation.name)? == LocalTagObservation::Absent {
73	            // Delegates to `GitAccess::create_tag` rather than inlining `git
74	            // tag` argv, so this inherits its `--` end-of-options separator
75	            // (defends `name` against being misread as a flag) on top of the
76	            // `--no-sign` this durable path has always needed (this repo's CI
77	            // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
78	            // with no tag-signing key available here).
79	            let git = GitAccess::new(context.root(), context.runner());
80	            git.create_tag(
81	                operation.name.as_str(),
82	                &operation.target,
83	                Some(&operation.annotation),
84	                TagSignPolicy::ForceUnsigned,
85	                effect.permit,
86	            )?;
87	        }
88	        let remote_endpoint = context.checked_git_remote()?.endpoint.clone();
89	        push_tag(context.runner(), context.root(), &remote_endpoint, operation)?;
90	        confirmed_evidence(
91	            tag_observation(context, operation)?,
92	            request.id,
93	            RemoteConflict::TagNotObservedAfterPush,
94	        )
95	    }
96	}
97	
98	/// GitHub's refusal when an App token pushes a ref whose tree's workflows
99	/// differ from every branch tip.
100	const WORKFLOW_GUARD_REFUSAL: &str = "refusing to allow a GitHub App to create or update workflow";
101	
102	fn push_tag(
103	    runner: &dyn CommandRunner,
104	    root: &Path,
105	    endpoint: &str,
106	    operation: &TagOperation,
107	) -> Result<(), GraphError> {
108	    let push_args = ["push", endpoint, operation.name.as_str()];
109	    let pushed = runner.run_with_timeout(programs::GIT, &push_args, root, timeouts::GIT_PUSH)?;
110	    if pushed.exit_code == Some(0) {
111	        return Ok(());
112	    }
113	    if pushed.stderr.contains(WORKFLOW_GUARD_REFUSAL) {
114	        return Err(GraphError::ReleaseTagPushRefusedWorkflowGuard {
115	            tag: operation.name.as_str().to_owned(),
116	            target: operation.target.as_str().to_owned(),
117	        });
118	    }
119	    Err(GraphError::ReleaseCommand {
120	        program: programs::GIT.to_string(),
121	        args: push_args.iter().map(ToString::to_string).collect(),
122	        failure: CommandFailure::NonZeroExit {
123	            exit_code: pushed.exit_code,
124	            stderr: pushed.stderr,
125	        },
126	    })
127	}
128	
129	fn tag_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a TagOperation, GraphError> {
130	    match request.operation {
131	        PreparedOperation::Tag(operation) => Ok(operation),
132	        _ => Err(wrong_role(request.id, "tag")),
133	    }
134	}
135	
136	/// The remote decides whether the tag operation is satisfied, but a local
137	/// ref that contradicts the prepared tag is still a conflict: the next push
138	/// would carry it.
139	fn tag_observation(
140	    context: &ProviderContext<'_>,
141	    operation: &TagOperation,
142	) -> Result<ProviderObservationV1, GraphError> {
143	    match observed_local_tag(context, &operation.name)? {
144	        LocalTagObservation::Absent => {}
145	        LocalTagObservation::Annotated { target: observed } if observed == operation.target => {}
146	        _ => {
147	            return Ok(ProviderObservationV1::Conflict {
148	                reason: ProviderConflictReason::LocalTagDiffers,
149	            })
150	        }
151	    }
152	    let remote = policy::retry_observation(context.sleeper(), || observed_remote_tag(context, &operation.name))?;
153	    Ok(match remote {
154	        RemoteTagObservation::Absent => ProviderObservationV1::Absent,
155	        RemoteTagObservation::Annotated { target: observed } if observed == operation.target => {
156	            ProviderObservationV1::Exact {
157	                evidence: ProviderEvidenceV1::GitTag {
158	                    peeled_commit: observed,
159	                },
160	            }
161	        }
162	        RemoteTagObservation::Annotated { .. } => ProviderObservationV1::Conflict {
163	            reason: ProviderConflictReason::RemoteTagTargetDiffers,
164	        },
165	        RemoteTagObservation::Unannotated => ProviderObservationV1::Conflict {
166	            reason: ProviderConflictReason::UnannotatedTag,
167	        },
168	        RemoteTagObservation::Indeterminate => ProviderObservationV1::Indeterminate {
169	            cause: ProviderIndeterminateCause::CommandFailed,
170	        },
171	    })
172	}
173	
174	/// Observes `refs/tags/<name>` on the prepared remote. A git failure leaves
175	/// the remote unknown; absence must be proved by a successful query. The
176	/// failure is transient: `ls-remote` is a read, so retrying it cannot have an
177	/// effect.
178	fn observed_remote_tag(
179	    context: &ProviderContext<'_>,
180	    name: &TagName,
181	) -> Result<Attempt<RemoteTagObservation>, GraphError> {
182	    let endpoint = context.checked_git_remote()?.endpoint.clone();
183	    let reference = format!("refs/tags/{name}");
184	    // The peeled ref resolves an annotated tag to its commit; a lightweight
185	    // tag has no peeled line at all.
186	    let peeled = format!("{reference}^{{}}");
187	    let args = ["ls-remote", endpoint.as_str(), reference.as_str(), peeled.as_str()];
188	    let observed = match run_observation(
189	        context.runner(),
190	        programs::GIT,
191	        &args,
