191	                observed_forge_release(
192	                    context,
193	                    &operation.tag,
194	                    operation.prerelease,
195	                    &repository,
196	                    Draft::PublishedOnly,
197	                )
198	            })?,
199	            request.id,
200	            RemoteConflict::ForgeReleaseNotObservedAfterPublish,
201	        )
202	    }
203	}
204	
205	/// Whether a still-draft release satisfies the observing role.
206	#[derive(Clone, Copy, PartialEq, Eq)]
207	enum Draft {
208	    Either,
209	    PublishedOnly,
210	}
211	
212	fn run_gh(context: &ProviderContext<'_>, args: &[&str], timeout: std::time::Duration) -> Result<(), GraphError> {
213	    let output = context
214	        .runner()
215	        .run_with_timeout(programs::GH, args, context.root(), timeout)?;
216	    if output.success() {
217	        return Ok(());
218	    }
219	    Err(GraphError::ReleaseCommand {
220	        program: programs::GH.to_owned(),
221	        args: args.iter().map(ToString::to_string).collect(),
222	        failure: CommandFailure::NonZeroExit {
223	            exit_code: output.exit_code,
224	            stderr: output.stderr,
225	        },
226	    })
227	}
228	
229	fn forge_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ForgeReleaseOperation, GraphError> {
230	    match request.operation {
231	        PreparedOperation::ForgeRelease(operation) => Ok(operation),
232	        _ => Err(wrong_role(request.id, "forge release")),
233	    }
234	}
235	
236	fn publish_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ForgePublishOperation, GraphError> {
237	    match request.operation {
238	        PreparedOperation::ForgePublish(operation) => Ok(operation),
239	        _ => Err(wrong_role(request.id, "forge publish")),
240	    }
241	}
