    runner: &dyn CommandRunner,
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    quiet: bool,
) -> Result<Result<CommandOutput, CommandUnavailable>, GraphError> {
    let result = if quiet {
        runner.run_quiet(program, args, cwd, timeout)
    } else {
        runner.run_with_timeout(program, args, cwd, timeout)
    };
    match result {
        Ok(output) => Ok(Ok(output)),
