fn p14_rerun_with_a_conflicting_existing_tag_fails_closed() {
    let e = Env::new(false);
    assert!(e.run(&[]).status.success());
    fs::remove_file(&e.receipt).unwrap();
    git(
        e.root(),
        &[
            "tag",
            "-a",
            "-f",
            "-m",
            "someone elses tag",
            "core-crate@0.2.0",
            "HEAD^",
        ],
    );
    let out = e.run(&[]);
    assert!(
        !out.status.success(),
        "a tag pointing at another commit is a conflict, not an exact success"
    );
    assert!(stderr(&out).contains("E167"), "{}", stderr(&out));
    assert!(!e.receipt.exists());
}

#[test]
fn p16_remote_asset_with_same_size_but_different_digest_is_a_conflict() {
    let e = Env::new(true);
    let (artifacts, manifest) = product_manifest(&e);
    let first = execute_product(e.root(), &e.intent, &manifest, &artifacts, &e.receipt, e.p());
    assert!(first.status.success(), "{}", stderr(&first));
    fs::remove_file(&e.receipt).unwrap();
    let marker = e.log.with_extension("artifact-marker");
    let tampered: Vec<String> = fs::read_to_string(&marker)
        .unwrap()
        .lines()
        .enumerate()
        .map(|(i, l)| {
            if i == 0 {
                let mut f: Vec<&str> = l.split('|').collect();
                let zero = "0".repeat(64);
                f[2] = &zero;
                f.join("|")
            } else {
                l.to_owned()
            }
        })
        .collect();
    fs::write(&marker, tampered.join("\n") + "\n").unwrap();
    let uploads = count(&e.log, "gh release upload");
    let out = execute_product(e.root(), &e.intent, &manifest, &artifacts, &e.receipt, e.p());
    assert!(!out.status.success(), "a differing remote asset must not be adopted");
    assert!(stderr(&out).contains("E167"), "{}", stderr(&out));
    assert_eq!(count(&e.log, "gh release upload"), uploads);
    assert!(!e.receipt.exists());
}
    let output = run.execute(&[]);
    assert!(
        output.status.success(),
        "an existing draft must be observed: {}\n{:?}",
        stderr_of(&output),
        run.rig.gh_calls()
    );
    let effects = run.release_effects();
    assert!(
        !effects.iter().any(|call| call.starts_with("release create")),
        "{effects:?}"
    );
    assert!(effects.iter().any(|call| call.contains("--draft=false")), "{effects:?}");
}

#[test]
fn a_draft_that_is_not_yet_visible_after_create_is_waited_for() {
    let mut run = ProductRun::new();
    run.rig.set("CALLISTO_TEST_FORGE_LAG", "2");

    let output = run.execute(&[]);
    assert!(
        output.status.success(),
        "a lagging read must not fail the release: {}\n{:?}",
        stderr_of(&output),
        run.rig.gh_calls()
    );
    let effects = run.release_effects();
    let creates = effects.iter().filter(|call| call.starts_with("release create")).count();
    assert_eq!(creates, 1, "{effects:?}");
    assert!(effects.iter().any(|call| call.contains("--draft=false")), "{effects:?}");
}

/// The release is not a pre-release, so a remote release flagged as one is a
/// different object than this intent authorized.
#[test]
fn a_prerelease_flag_mismatch_is_a_conflict_and_issues_no_effect() {
    let run = ProductRun::new();
    fs::write(&run.rig.forge_marker, "published").unwrap();
    fs::write(run.rig.forge_marker.with_extension("prerelease"), "").unwrap();

    let output = run.execute(&[]);
    assert!(
        !output.status.success(),
        "a disagreeing prerelease flag must stop the release: {:?}",
        run.rig.gh_calls()
    );
    let effects = run.release_effects();
    assert!(
        effects.is_empty(),
        "a conflicting forge release must be observed, not edited: {effects:?}"
    );
    assert!(
        diagnostic_codes(&output).iter().any(|code| code == "E167"),
        "the failure must be the typed remote-conflict, not an unrelated error: {}",
        stderr_of(&output)
    );
}

