    #[test]
    fn a_package_untouched_since_its_version_commit_is_not_reported() {
        let (dir, _) = fixture();
        assert!(moved(dir.path()).is_empty());
    }

    #[test]
    fn a_later_commit_in_the_package_is_reported_with_the_version_commit() {
        let (dir, _) = fixture();
        let version_commit = git(dir.path(), &["rev-parse", "HEAD"]);
        std::fs::write(dir.path().join("NOTES.md"), "later\n").unwrap();
        commit_all(dir.path(), "later");
        assert_eq!(
            moved(dir.path()),
            vec![("cargo/release-fixture".to_owned(), Some(version_commit))]
        );
    }

    #[test]
    fn a_commit_in_another_package_is_not_a_move() {
        let (dir, _) = fixture();
        let root = dir.path();
        let version_commit = inheriting_workspace(root);
        std::fs::write(root.join("crates/b/src/lib.rs"), "pub fn b() {}\n").unwrap();
        commit_all(root, "change b");
        assert_eq!(moved(root), vec![("cargo/b".to_owned(), Some(version_commit))]);
    }

    #[test]
    fn an_inherited_version_is_located_at_the_workspace_manifest_that_set_it() {
        let (dir, _) = fixture();
        let root = dir.path();
        let version_commit = inheriting_workspace(root);
        std::fs::write(root.join("crates/a/src/lib.rs"), "pub fn a() {}\n").unwrap();
        commit_all(root, "change a");
        assert_eq!(
            moved(root),
            vec![("cargo/a".to_owned(), Some(version_commit))],
            "a package that inherits its version is checked like any other"
        );
    }

    #[test]
    fn a_version_set_long_ago_is_still_found() {
        let (dir, _) = fixture();
        let root = dir.path();
        let version_commit = git(root, &["rev-parse", "HEAD"]);
        let manifest = root.join("Cargo.toml");
        let original = std::fs::read_to_string(&manifest).unwrap();
        for index in 0..105 {
            std::fs::write(&manifest, format!("{original}\n# edit {index}\n")).unwrap();
            commit_all(root, "touch the manifest");
        }
        assert_eq!(
            moved(root),
            vec![("cargo/release-fixture".to_owned(), Some(version_commit))],
            "more than a hundred manifest edits above the version commit must not hide it"
        );
    }

    #[test]
    fn a_release_branch_merged_after_unrelated_trunk_commits_is_not_a_move() {
        let (dir, _) = fixture();
        let root = dir.path();
        git(root, &["switch", "-q", "-c", "trunk"]);
        git(root, &["switch", "-q", "-c", "release"]);
        let manifest = root.join("Cargo.toml");
        let text = std::fs::read_to_string(&manifest).unwrap();
        std::fs::write(&manifest, text.replace("1.2.3", "1.3.0")).unwrap();
        commit_all(root, "release 1.3.0");
        git(root, &["switch", "-q", "trunk"]);
        std::fs::write(root.join("NOTES.md"), "trunk moved on\n").unwrap();
        commit_all(root, "trunk moved on");
        git(root, &["merge", "-q", "--no-ff", "-m", "merge the release", "release"]);
        assert!(
            moved(root).is_empty(),
            "HEAD is the merge that landed the version, so nothing differs from the commit that set it"
        );
    }

    #[test]
    fn a_version_no_commit_set_is_reported_without_a_commit() {
        let (dir, _) = fixture();
        let root = dir.path();
        let manifest = root.join("Cargo.toml");
        let text = std::fs::read_to_string(&manifest).unwrap();
        let bumped = text.replacen("version = \"", "version = \"9", 1);
        std::fs::write(&manifest, bumped).unwrap();
        // Uncommitted: no commit holds this version, so the guard cannot say it is unchanged.
        assert!(moved(root).iter().all(|(_, commit)| commit.is_none()));
    }
}
/// A release that stopped after publishing is finished from the commit that set the version: a later commit in the
/// package would be tagged with code the registry never received.
#[test]
fn a_published_version_is_not_tagged_on_a_later_commit() {
    let (dir, release_commit) = on_branch();
    let root = dir.path();
    let rig = Rig::new(&release_commit);
    fs::write(format!("{}.core-crate", registry_marker(root).display()), "0.2.0").unwrap();
    fs::write(
        root.join("crates/core/src/lib.rs"),
        "pub fn core() {}\n// changed after the version\n",
    )
    .unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "change core after the version"]);

    let refused = rig.run(root, &["release"]);
    assert!(!refused.status.success(), "{}", stderr(&refused));
    assert!(stderr(&refused).contains("E320"), "{}", stderr(&refused));
    assert_no_effects(&rig, root);

    git(root, &["checkout", "--detach", "-q", &release_commit]);
    let finished = rig.run(root, &["release"]);
    assert!(finished.status.success(), "{}", stderr(&finished));
    assert_eq!(git(root, &["rev-list", "-n", "1", "core-crate@0.2.0"]), release_commit);
    assert_eq!(
        rig.effects().matches("cargo publish").count(),
        0,
        "adopted, not published again"
    );
}

/// A first release whose version the registry holds for another repository is that project's, so it is refused.
#[test]
fn a_first_release_of_a_name_another_project_published_is_refused_before_any_effect() {
    let (dir, release_commit) = on_branch();
    let root = dir.path();
    let rig = Rig::new(&release_commit);
    fs::write(format!("{}.core-crate", registry_marker(root).display()), "0.2.0").unwrap();
    set_registry_repository(root, "https://github.com/someone-else/core-crate.git");

    for args in [&["release"][..], &["release", "--dry-run"][..]] {
        let refused = rig.run(root, args);
        assert!(!refused.status.success(), "{args:?}: {}", stderr(&refused));
        assert!(stderr(&refused).contains("E322"), "{args:?}: {}", stderr(&refused));
        assert_no_effects(&rig, root);
    }

    set_registry_repository(root, "git+https://GitHub.com/Example/core-crate.git");
    let same = rig.run(root, &["release", "--dry-run"]);
    assert!(same.status.success(), "{}", stderr(&same));
}

/// The preview of an interrupted release shows the remaining work, and a selected package whose
/// release is complete is still not a release.
#[test]
fn a_dry_run_after_a_failed_tag_push_plans_the_remaining_operations() {
    let (dir, release_commit) = on_branch();
    let root = dir.path();
    let rig = Rig::new(&release_commit);
    let flag = rig.external.path().join("fail-pushes");
