1	//! The one changelog-section reader behind release notes.
2	
3	use std::collections::HashSet;
4	use std::path::Path;
5	
6	use callisto_model::Version;
7	
8	use crate::error::GraphError;
9	
10	use super::provider::{NotesFallback, ReleaseNotes};
11	
12	/// The non-empty `## {version}` section of the changelog at `root.join(changelog)`, or why there is none. A changelog
13	/// that is there but cannot be read is an error, not a reason: the notes would silently differ from what was reviewed.
14	fn changelog_section(
15	    root: &Path,
16	    changelog: &Path,
17	    version: &Version,
18	) -> Result<Result<String, NotesFallback>, GraphError> {
19	    let path = root.join(changelog);
20	    let content = match callisto_model::strict_fs::read_optional(&path) {
21	        Ok(Some(content)) => content,
22	        Ok(None) => return Ok(Err(NotesFallback::FileMissing)),
23	        Err(error) => {
24	            return Err(GraphError::ReleaseInputRead {
25	                path,
26	                message: error.to_string(),
27	            })
28	        }
29	    };
30	    Ok(match crate::changelog::find_section(&content, version) {
31	        None => Err(NotesFallback::SectionMissing),
32	        Some("") => Err(NotesFallback::SectionEmpty),
33	        Some(section) => Ok(section.to_owned()),
34	    })
35	}
36	
37	/// Release notes for a package: its changelog section, else generated notes and why.
38	///
39	/// # Errors
40	///
41	/// The changelog exists but cannot be read.
42	pub(crate) fn release_notes(
43	    root: &Path,
44	    changelog: Option<&Path>,
45	    version: &Version,
46	) -> Result<ReleaseNotes, GraphError> {
47	    let Some(changelog) = changelog else {
48	        return Ok(ReleaseNotes::Generated {
49	            reason: NotesFallback::NotConfigured,
50	        });
51	    };
52	    Ok(match changelog_section(root, changelog, version)? {
53	        Ok(section) => ReleaseNotes::Section(section),
54	        Err(reason) => ReleaseNotes::Generated { reason },
55	    })
56	}
57	
58	/// A fixed-group member's changelog line that only says it was released with the group.
59	fn is_group_boilerplate(entry: &str) -> bool {
60	    entry.starts_with("- Released together with the `") || entry.starts_with("- Joined the `")
61	}
62	
63	/// The changelog entries of a section: each `- ` bullet with its indented continuation lines.
64	fn entries(section: &str) -> Vec<String> {
65	    let mut entries: Vec<String> = Vec::new();
66	    for line in section.lines() {
67	        match entries.last_mut() {
68	            Some(last) if line.starts_with(' ') || line.is_empty() => {
69	                last.push('\n');
70	                last.push_str(line);
71	            }
72	            _ if line.starts_with("- ") => entries.push(line.to_owned()),
73	            _ => {}
74	        }
75	    }
76	    entries.iter().map(|entry| entry.trim_end().to_owned()).collect()
77	}
78	
79	/// The section with its group boilerplate bullets removed; every other line is kept as written.
80	fn without_boilerplate(section: &str) -> String {
81	    let mut kept: Vec<&str> = Vec::new();
82	    let mut skipping = false;
83	    for line in section.lines() {
84	        if is_group_boilerplate(line) {
85	            skipping = true;
86	        } else if skipping && line.starts_with(' ') {
87	            continue;
88	        } else {
89	            skipping = false;
90	            if !(line.is_empty() && kept.last().is_none_or(|last| last.is_empty())) {
91	                kept.push(line);
92	            }
